```c
void PackRumbleSample(const RumbleSample* in, PackedRumbleSample* out) {
    uint64_t packed =  (uint64_t)(in->freq0 & 0x3FF)
                    | ((uint64_t)(in->amp0  & 0x3FF) << 10)
                    | ((uint64_t)(in->freq1 & 0x3FF) << 20)
                    | ((uint64_t)(in->amp1  & 0x3FF) << 30);

    out->data[0] =  packed        & 0xFF;
    out->data[1] = (packed >> 8)  & 0xFF;
    out->data[2] = (packed >> 16) & 0xFF;
    out->data[3] = (packed >> 24) & 0xFF;
    out->data[4] = (packed >> 32) & 0xFF;
}

void UnpackRumbleSample(const PackedRumbleSample* in, RumbleSample* out) {
    uint64_t packed = ((uint64_t)in->data[0])
                    | ((uint64_t)in->data[1] << 8)
                    | ((uint64_t)in->data[2] << 16)
                    | ((uint64_t)in->data[3] << 24)
                    | ((uint64_t)in->data[4] << 32);

    out->freq0 =  packed        & 0x3FF;
    out->amp0  = (packed >> 10) & 0x3FF;
    out->freq1 = (packed >> 20) & 0x3FF;
    out->amp1  = (packed >> 30) & 0x3FF;
}
